import {biographyHTML,biographyFor} from './biography.js';
import {searchable,localize,currentLanguage} from './i18n.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const professions={PIONEER:'先锋',WARRIOR:'近卫',TANK:'重装',SNIPER:'狙击',CASTER:'术师',MEDIC:'医疗',SUPPORT:'辅助',SPECIAL:'特种'};
export function createOperatorsPage(root,{data,onRegion}){
 const ops=data.operators;let mode='origins',category='乌萨斯',query='';
 const dialog=document.createElement('dialog');dialog.className='leader-dialog';dialog.setAttribute('aria-labelledby','operator-profile-name');document.body.append(dialog);let trigger;
 const image=o=>`<img src="${esc(o.image)}" alt="${esc(o.name)}游戏头像" loading="lazy" width="180" height="180">`;
 const isOrigin=()=>mode==='origins';
 const key=()=>isOrigin()?'origin':'race';
 function open(id){const o=ops.find(o=>o.id===id);if(!o)return;trigger=document.activeElement;
 dialog.innerHTML=`<button class="leader-close" aria-label="关闭干员介绍">×</button><div class="leader-profile"><div class="leader-art">${image(o)}</div><div><span class="eyebrow">RHODES ISLAND / OPERATOR</span><h2 id="operator-profile-name">${esc(o.name)}</h2><p>${'★'.repeat(o.rarity)} · ${professions[o.profession]||o.profession}</p>${o.newEvent?`<p class="leader-alias">《${esc(o.newEvent)}》版本收录</p>`:''}</div></div><div class="leader-body"><section><h3>基础档案</h3><dl><dt>${esc(o.originLabel)}</dt><dd>${esc(o.origin)}</dd><dt>种族</dt><dd>${esc(o.race)}</dd><dt>性别</dt><dd>${esc(o.sex)}</dd><dt>${esc(o.birthdayLabel)}</dt><dd>${esc(o.birthday)}</dd></dl></section>${biographyHTML(o.name)}<section><h3>档案说明</h3><p class="tiny">出身地不等于国籍、现居地或所属组织。合作干员也不一定是罗德岛正式雇员。含剧情剧透。</p></section><section><h3>继续查阅</h3><div class="leader-region-links"><button data-operator-category="origin">查看${esc(o.origin)}出身的干员</button><button data-operator-category="race">查看${esc(o.race)}干员</button></div><p class="tiny">国服档案核对：${esc(data.checked)} · 截至《${esc(data.cutoffEvent)}》</p><a class="source-link" href="${esc(o.source)}" target="_blank" rel="noopener noreferrer">BWIKI · ${esc(o.name)} ↗</a><a class="source-link" href="${esc(o.gameSource)}" target="_blank" rel="noopener noreferrer">游戏档案数据（公开镜像）↗</a></section></div>`;
 dialog.querySelector('.leader-close').onclick=()=>dialog.close();dialog.querySelectorAll('[data-operator-category]').forEach(b=>b.onclick=()=>{dialog.close();category=o[b.dataset.operatorCategory];query='';root.dispatchEvent(new CustomEvent('operator-mode',{detail:b.dataset.operatorCategory==='origin'?'origins':'races',bubbles:true}));});dialog.showModal();dialog.scrollTop=0;document.body.classList.add('person-open');}
 dialog.addEventListener('close',()=>{document.body.classList.remove('person-open');trigger?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
 function render(next){mode=next;const field=key();const groups=[...new Set(ops.map(o=>o[field]))].sort((a,b)=>localize(a).localeCompare(localize(b),currentLanguage()));if(!groups.includes(category))category=groups.includes('乌萨斯')?'乌萨斯':groups[0];
 root.innerHTML=`<div class="leaders-wrap leaders-layout"><aside class="leader-sidebar" aria-label="${isOrigin()?'出身地':'种族'}列表"><span class="eyebrow">OPERATOR ARCHIVE</span><h1>${isOrigin()?'干员来自哪里':'干员种族'}</h1><p>${ops.length} 个干员条目<br>截至《${esc(data.cutoffEvent)}》</p><h2>${isOrigin()?'按档案出身地':'按档案种族'}</h2>${groups.map(g=>`<button data-operator-group="${esc(g)}"><span>${esc(g)}</span><small>${ops.filter(o=>o[field]===g).length}</small></button>`).join('')}</aside><div class="leader-main"><header id="operator-heading"></header><div class="leader-filters"><label>检索干员 <input type="search" aria-label="搜索干员" placeholder="搜索全体干员姓名…" value="${esc(query)}"></label><span id="operator-count" aria-live="polite"></span></div><div class="leader-catalog operator-catalog"></div></div></div>`;
 root.querySelectorAll('[data-operator-group]').forEach(b=>b.onclick=()=>{category=b.dataset.operatorGroup;query='';root.querySelector('input').value='';update();root.querySelector('.leader-main').scrollIntoView({block:'start',behavior:'instant'});});root.querySelector('input').oninput=e=>{query=e.target.value;update();};update();}
 function update(){const field=key(),q=query.trim().toLowerCase();const list=ops.filter(o=>q?searchable(o.name,q):o[field]===category).sort((a,b)=>Number(!!b.newEvent)-Number(!!a.newEvent)||b.rarity-a.rarity||localize(a.name).localeCompare(localize(b.name),currentLanguage()));
 root.querySelectorAll('[data-operator-group]').forEach(b=>{const active=!q&&b.dataset.operatorGroup===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 root.querySelector('#operator-heading').innerHTML=`<span class="eyebrow">${isOrigin()?'ORIGINS / 出身地':'RACES / 种族'}</span><h2>${esc(q?'检索结果':category)}</h2><p>${isOrigin()?'依据游戏基础档案的“出身地”分类；作业平台等采用“产地”，卡片会注明字段。保留原始写法。':'依据游戏基础档案的“种族”分类，复合种族保留原文，不推测未公开身份。'}</p><small>异格独立展示，阿米娅职业升变不重复计数。${esc(data.checked)} 国服快照。</small>`;
 root.querySelector('#operator-count').textContent=`${list.length} 位干员`;
 root.querySelector('.operator-catalog').innerHTML=list.length?list.map(o=>`<button class="leader-tile" data-operator="${o.id}"><strong class="leader-rank">${esc(o[field])}</strong><div class="leader-tile-content"><div class="leader-tile-art">${image(o)}</div><div class="leader-tile-copy"><span class="eyebrow">${professions[o.profession]} / ${'★'.repeat(o.rarity)}</span><h2>${esc(o.name)}</h2>${o.newEvent?'<span class="operator-new">时间啊，向前！</span>':''}<p>${esc(o.originLabel)}：${esc(o.origin)}<br>种族：${esc(o.race)}</p><p class="operator-excerpt">${esc(biographyFor(o.name)?.sentences[0]||'')}</p><span class="leader-read">阅读干员档案 →</span></div></div></button>`).join(''):'<p class="fact-note">没有匹配的干员，请换一个关键词。</p>';
 root.querySelectorAll('[data-operator]').forEach(b=>b.onclick=()=>open(b.dataset.operator));}
 document.addEventListener('terramap-language',()=>{if(!root.hidden&&root.childElementCount)render(mode);});
 return {render,open};
}
